tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in storygame/story_package/models.py storygame/runtime/engine.py tests/test_story_ending.py tests/test_lighthouse_ending.py; do git status --porcelain -- $f | grep -q . || { echo "WHY: $f not modified"; exit 1; }; done
grep -n "class EndingVariant" storygame/story_package/models.py || { echo "WHY: EndingVariant missing"; exit 1; }
grep -rniE "lighthouse|continuity|kristin" storygame/story_package/models.py storygame/story_package/loader.py storygame/runtime/engine.py && { echo "WHY: story-specific id in engine"; exit 1; }
CH=$(git status --porcelain | awk '{print $NF}')
for f in $CH; do case "$f" in storygame/story_package/models.py|storygame/story_package/loader.py|storygame/runtime/engine.py|tests/test_story_ending.py|tests/test_lighthouse_ending.py|tests/fixtures/stories/lighthouse-incident/pacing.yaml) ;; .plans/*|scripts/ringer/*|tests/test_act2_probe.py|storygame/audit.py|storygame/runtime/cloudflare.py|tests/test_incident_loader.py|tests/fixtures/stories/lighthouse-incident/*|data/stories/continuity-initiative/plot.md) ;; *) echo "WHY: unexpected changed file: $f"; exit 1;; esac; done
git diff --quiet -- data/stories/continuity-initiative/pacing.yaml || { echo "WHY: continuity pacing.yaml was edited"; exit 1; }
$PY -m ruff format --check storygame tests || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check storygame tests/test_story_ending.py tests/test_lighthouse_ending.py || { echo "WHY: ruff check failed"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_story_ending.py tests/test_lighthouse_ending.py tests/test_incident_loader.py tests/test_incident_engine.py tests/test_world_second_package.py tests/test_3c_cue_chain.py tests/test_markdown_story_package.py || { echo "WHY: suites failed"; exit 1; }
echo ok
